class Solution { public: int minimumOperations(vector<vector<int>>& grid) {
 int m=grid.size(),n=grid[0].size();vector<int> dp(10,0);
 for(int j=0;j<n;++j){int cnt[10]={};for(int i=0;i<m;++i)++cnt[grid[i][j]];vector<int> nd(10,INT_MAX/4);for(int d=0;d<10;++d){int best=INT_MAX/4;if(j==0)best=0;else for(int p=0;p<10;++p)if(p!=d)best=min(best,dp[p]);nd[d]=best+m-cnt[d];}dp.swap(nd);}return *min_element(dp.begin(),dp.end());
}};
